import { helloCall } from '../../../engine/client'
import { PNPM_BUILD_STAGE } from '../../../engine/docker'
import { camelCase, pascalCase, upperSnake } from '../../../engine/names'
import { json, readPluginFiles } from '../../../engine/tree'
import type { AppContext, FileTree, FrameworkPlugin, ResolvedApp } from '../../types'

const urlVar = (b: ResolvedApp) => `${upperSnake(b.name)}_URL`
const clientVar = (b: ResolvedApp) => `${camelCase(b.name)}Client`
/** Name order matches Biome's import sorting, so the generated files pass `biome check` as is. */
const byName = (backends: ResolvedApp[]) =>
  [...backends].sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))

/** Lives under server/ so Nitro keeps it (and the backend URLs) out of the browser bundle. */
function apiFile(ctx: AppContext): string {
  if (ctx.backends.length === 0) {
    return '// Generated by octorepo. Do not edit: regenerated by `add`.\nexport {}\n'
  }
  const backends = byName(ctx.backends)
  const imports = backends.map(
    (b) =>
      `import { createClient as create${pascalCase(b.name)} } from '${ctx.scope}/${b.name}-client'`,
  )
  const clients = backends.map(
    (b) => `const ${camelCase(b.name)}Url = process.env.${urlVar(b)} ?? 'http://localhost:${b.port}'
export const ${clientVar(b)} = create${pascalCase(b.name)}(${camelCase(b.name)}Url)`,
  )
  return `// Generated by octorepo. Do not edit: regenerated by \`add\`.
// Server-side only: backend URLs come from runtime env and are never exposed to the browser.
// Read from process.env (not runtimeConfig), so it's the same <NAME>_URL every SSR app uses.
${imports.join('\n')}

${clients.join('\n\n')}
`
}

/** Server route the page calls during SSR; it runs per request, so builds never reach backends. */
function helloRoute(ctx: AppContext): string {
  const calls = byName(ctx.backends)
    .map((b) => helloCall(b.name, clientVar(b)))
    .join('\n')
  return `import { type BackendResult, type CardProps, toCard } from '../../shared/cards'
import { ${byName(ctx.backends).map(clientVar).join(', ')} } from '../generated/api'

async function hello(
  name: string,
  call: (signal: AbortSignal) => Promise<{ data?: { message: string }; error?: unknown }>,
): Promise<BackendResult> {
  try {
    // Bounded, so a hanging backend renders "unreachable" instead of stalling the page.
    const { data, error } = await call(AbortSignal.timeout(3000))
    return { name, data, error }
  } catch (error) {
    return { name, error }
  }
}

export default defineEventHandler(async (): Promise<CardProps[]> => {
  const results = await Promise.all([
${calls}
  ])
  return results.map(toCard)
})
`
}

function pageFile(ctx: AppContext): string {
  const { app, scope } = ctx
  if (ctx.backends.length === 0) {
    return `<script setup lang="ts">
import { Card } from '${scope}/ui-vue'
</script>

<template>
  <main>
    <h1>${app.name}</h1>
    <Card title="${app.name}">Hello from ${app.name}</Card>
  </main>
</template>
`
  }
  return `<script setup lang="ts">
import { Card } from '${scope}/ui-vue'

// Fetched from the server route during SSR (per request) and hydrated from the payload.
const { data: cards } = await useFetch('/api/hello', { default: () => [] })
</script>

<template>
  <main>
    <h1>${app.name}</h1>
    <Card v-for="card in cards" :key="card.title" :title="card.title">{{ card.body }}</Card>
  </main>
</template>
`
}

function generate(ctx: AppContext): FileTree {
  const { app, scope, versions: v, backends } = ctx
  const dir = `apps/${app.name}`
  const files = readPluginFiles(new URL('./', import.meta.url), { name: app.name, scope })
  const tree: FileTree = {}
  for (const [path, content] of Object.entries(files)) tree[`${dir}/${path}`] = content
  tree[`${dir}/app/app.vue`] = pageFile(ctx)
  tree[`${dir}/server/generated/api.ts`] = apiFile(ctx)
  if (backends.length > 0) tree[`${dir}/server/api/hello.get.ts`] = helloRoute(ctx)
  tree[`${dir}/.env.example`] =
    `${backends.map((b) => `${urlVar(b)}=http://localhost:${b.port}`).join('\n')}${backends.length > 0 ? '\n' : ''}`
  tree[`${dir}/package.json`] = json({
    name: `${scope}/${app.name}`,
    version: '0.0.0',
    private: true,
    type: 'module',
    scripts: {
      dev: `nuxt dev --port ${app.port}`,
      build: 'nuxt build',
      start: 'node .output/server/index.mjs',
      lint: 'biome check .',
      typecheck: 'nuxt typecheck',
      test: 'vitest run',
    },
    dependencies: {
      [`${scope}/ui-vue`]: 'workspace:*',
      ...Object.fromEntries(backends.map((b) => [`${scope}/${b.name}-client`, 'workspace:*'])),
      nuxt: v.nuxt,
      vue: v.vue,
      'vue-router': v['vue-router'],
    },
    devDependencies: {
      '@biomejs/biome': v['@biomejs/biome'],
      '@types/node': v['@types/node'],
      typescript: v.typescript,
      vitest: v.vitest,
      'vue-tsc': v['vue-tsc'],
    },
  })
  return tree
}

function dockerfile(ctx: AppContext): string {
  const pkg = `${ctx.scope}/${ctx.app.name}`
  const dir = `apps/${ctx.app.name}`
  const port = ctx.app.port
  // Nitro's node-server output is self-contained: .output bundles the server and its node_modules.
  return `${PNPM_BUILD_STAGE}RUN pnpm --filter ${pkg}... build

FROM node:24-alpine AS runtime
ENV NODE_ENV=production
ENV PORT=${port}
ENV HOST=0.0.0.0
WORKDIR /app
COPY --from=build --chown=node:node /repo/${dir}/.output ./.output
USER node
EXPOSE ${port}
HEALTHCHECK --interval=30s --timeout=3s --start-period=10s CMD node -e "fetch('http://127.0.0.1:' + process.env.PORT + '/').then((r) => process.exit(r.ok ? 0 : 1)).catch(() => process.exit(1))"
CMD ["node",".output/server/index.mjs"]
`
}

export const nuxtPlugin: FrameworkPlugin = {
  id: 'nuxt',
  kind: 'frontend',
  label: 'Nuxt',
  apiStyles: [],
  defaultPort: 3000,
  uiFamily: 'vue',
  rendering: 'ssr',
  generate,
  dockerfile,
}
